INSERT INTO jsh_daily_out_summary ( material_id, bar_code, material_name, out_date, total_out_quantity, depot_count, bill_count, tenant_id ) SELECT di.material_id, me.bar_code, m.name as material_name, DATE(dh.oper_time) as out_date, SUM(IFNULL(di.basic_number, 0)) as total_out_quantity, COUNT(DISTINCT di.depot_id) as depot_count, COUNT(DISTINCT dh.id) as bill_count, dh.tenant_id FROM jsh_depot_item di LEFT JOIN jsh_depot_head dh ON dh.id = di.header_id LEFT JOIN jsh_material m ON m.id = di.material_id LEFT JOIN jsh_material_extend me ON me.material_id = m.id AND IFNULL(me.delete_flag,'0') != '1' AND me.default_flag = 1 WHERE dh.type = '出库' AND IFNULL(di.delete_flag,'0') != '1' AND IFNULL(dh.delete_flag,'0') != '1' AND IFNULL(m.delete_flag,'0') != '1' AND dh.status = '1' AND dh.oper_time >= DATE_SUB(CURDATE(), INTERVAL #{days} DAY)
AND IFNULL(dh.tenant_id, 0) = #{tenantId}
GROUP BY di.material_id, DATE(dh.oper_time), dh.tenant_id ON DUPLICATE KEY UPDATE bar_code = VALUES(bar_code), material_name = VALUES(material_name), total_out_quantity = VALUES(total_out_quantity), depot_count = VALUES(depot_count), bill_count = VALUES(bill_count), last_update_time = CURRENT_TIMESTAMP

