SELECT di.material_id AS materialId, IFNULL(SUM(di.basic_number), 0) AS sixMonthsSales FROM jsh_depot_item di INNER JOIN jsh_depot_head dh ON dh.id = di.header_id WHERE dh.type = '出库' AND dh.sub_type = '销售' AND dh.status = '1' AND IFNULL(di.delete_flag, '0') != '1' AND IFNULL(dh.delete_flag, '0') != '1' AND dh.oper_time >= DATE_SUB(CURDATE(), INTERVAL 6 MONTH)
AND dh.tenant_id = #{tenantId}
AND di.material_id IN
#{mid}
GROUP BY di.material_id

