INSERT INTO jsh_daily_out_summary (material_id, bar_code, material_name, out_date, shop_name, total_out_quantity, depot_count, bill_count) VALUES ( #{materialId}, (SELECT me.bar_code FROM jsh_material_extend me WHERE me.material_id = #{materialId} AND me.default_flag = 1 LIMIT 1), (SELECT m.name FROM jsh_material m WHERE m.id = #{materialId} LIMIT 1), #{targetDate}, #{shopName}, (SELECT COUNT(DISTINCT di.depot_id) FROM jsh_depot_item di INNER JOIN jsh_depot_head dh ON dh.id = di.header_id WHERE di.material_id = #{materialId} AND DATE(dh.oper_time) = #{targetDate} AND dh.type = '出库' AND dh.sub_type = '销售' AND dh.status = '1' AND IFNULL(di.delete_flag, '0') != '1' AND IFNULL(dh.delete_flag, '0') != '1'
AND dh.tenant_id = #{tenantId}
), (SELECT COUNT(DISTINCT dh.id) FROM jsh_depot_item di INNER JOIN jsh_depot_head dh ON dh.id = di.header_id WHERE di.material_id = #{materialId} AND DATE(dh.oper_time) = #{targetDate} AND dh.type = '出库' AND dh.sub_type = '销售' AND dh.status = '1' AND IFNULL(di.delete_flag, '0') != '1' AND IFNULL(dh.delete_flag, '0') != '1'
AND dh.tenant_id = #{tenantId}
) ) ON DUPLICATE KEY UPDATE bar_code = VALUES(bar_code), material_name = VALUES(material_name), shop_name = VALUES(shop_name), total_out_quantity = VALUES(total_out_quantity), depot_count = VALUES(depot_count), bill_count = VALUES(bill_count), last_update_time = CURRENT_TIMESTAMP

