INSERT INTO jsh_material_period_summary ( material_id, bar_code, material_name, material_model, material_unit, current_period_stock, previous_period_stock, current_period_out, previous_period_out, current_period_in, previous_period_in ) VALUES ( #{materialId}, (SELECT me.bar_code FROM jsh_material_extend me WHERE me.material_id = #{materialId} AND me.default_flag = 1 LIMIT 1), (SELECT m.name FROM jsh_material m WHERE m.id = #{materialId} LIMIT 1), (SELECT m.model FROM jsh_material m WHERE m.id = #{materialId} LIMIT 1), (SELECT m.unit FROM jsh_material m WHERE m.id = #{materialId} LIMIT 1), -- 当前库存 (SELECT IFNULL(SUM(mcs.current_number), 0) FROM jsh_material_current_stock mcs WHERE mcs.material_id = #{materialId} AND mcs.delete_flag = '0'
AND mcs.tenant_id = #{tenantId}
), -- 上期结存（暂时设为0，后续可优化） 0, -- 本期出库 (SELECT IFNULL(SUM(di.basic_number), 0) FROM jsh_depot_item di INNER JOIN jsh_depot_head dh ON dh.id = di.header_id WHERE di.material_id = #{materialId} AND dh.type = '出库' AND dh.status = '1' AND IFNULL(di.delete_flag, '0') != '1' AND IFNULL(dh.delete_flag, '0') != '1'
AND dh.tenant_id = #{tenantId}
), -- 上期出库（暂时设为0，后续可优化） 0, -- 本期入库 (SELECT IFNULL(SUM(di.basic_number), 0) FROM jsh_depot_item di INNER JOIN jsh_depot_head dh ON dh.id = di.header_id WHERE di.material_id = #{materialId} AND dh.type = '入库' AND dh.status = '1' AND IFNULL(di.delete_flag, '0') != '1' AND IFNULL(dh.delete_flag, '0') != '1'
AND dh.tenant_id = #{tenantId}
), -- 上期入库（暂时设为0，后续可优化） 0 ) ON DUPLICATE KEY UPDATE bar_code = VALUES(bar_code), material_name = VALUES(material_name), material_model = VALUES(material_model), material_unit = VALUES(material_unit), current_period_stock = VALUES(current_period_stock), previous_period_stock = VALUES(previous_period_stock), current_period_out = VALUES(current_period_out), previous_period_out = VALUES(previous_period_out), current_period_in = VALUES(current_period_in), previous_period_in = VALUES(previous_period_in), last_calculation_time = CURRENT_TIMESTAMP

mapper.delete:
