SELECT IFNULL(SUM(di.basic_number), 0)
FROM jsh_depot_item di 
INNER JOIN jsh_depot_head dh ON dh.id = di.header_id 
WHERE di.material_id = #{materialId} 
  AND dh.type = '出库' 
  AND dh.status = '1'
  AND IFNULL(di.delete_flag, '0') != '1'
  AND IFNULL(dh.delete_flag, '0') != '1'
  AND DATE(dh.oper_time) >= #{startDate}
  AND DATE(dh.oper_time) <= #{endDate}

      AND dh.tenant_id = #{tenantId}

SELECT IFNULL(SUM(di.basic_number), 0)
FROM jsh_depot_item di 
INNER JOIN jsh_depot_head dh ON dh.id = di.header_id 
WHERE di.material_id = #{materialId} 
  AND dh.type = '入库' 
  AND dh.status = '1'
  AND IFNULL(di.delete_flag, '0') != '1'
  AND IFNULL(dh.delete_flag, '0') != '1'
  AND DATE(dh.oper_time) >= #{startDate}
  AND DATE(dh.oper_time) <= #{endDate}

      AND dh.tenant_id = #{tenantId}

SELECT IFNULL(SUM(mcs.current_number), 0)
FROM jsh_material_current_stock mcs 
WHERE mcs.material_id = #{materialId} 
  AND mcs.delete_flag = '0'

      AND mcs.tenant_id = #{tenantId}

mapper.insert:
-- 先初始化商品期间汇总表 INSERT INTO jsh_material_period_summary ( material_id, bar_code, material_name, material_model, material_unit, current_period_stock, previous_period_stock, current_period_out, previous_period_out, current_period_in, previous_period_in ) SELECT m.id as material_id, me.bar_code, m.name as material_name, m.model as material_model, m.unit as material_unit, COALESCE(cs.current_stock, 0) as current_period_stock, GREATEST(0, COALESCE(cs.current_stock, 0) - COALESCE(ci.current_in, 0) + COALESCE(co.current_out, 0)) as previous_period_stock, COALESCE(co.current_out, 0) as current_period_out, COALESCE(po.previous_out, 0) as previous_period_out, COALESCE(ci.current_in, 0) as current_period_in, COALESCE(pi.previous_in, 0) as previous_period_in FROM jsh_material m LEFT JOIN jsh_material_extend me ON m.id = me.material_id AND me.default_flag = '1' AND COALESCE(me.tenant_id, m.tenant_id) = m.tenant_id LEFT JOIN ( -- 当前库存 SELECT material_id, tenant_id, SUM(current_number) as current_stock FROM jsh_material_current_stock WHERE delete_flag = '0' GROUP BY material_id, tenant_id ) cs ON m.id = cs.material_id AND m.tenant_id = cs.tenant_id LEFT JOIN ( -- 本期出库（根据当前月份动态判断期间） SELECT di.material_id, dh.tenant_id, SUM(di.basic_number) as current_out FROM jsh_depot_head dh INNER JOIN jsh_depot_item di ON dh.id = di.header_id WHERE dh.type = '出库' AND dh.status = '1' AND dh.delete_flag = '0' AND di.delete_flag = '0' AND ( -- 本期时间范围：根据当前月份动态判断 (MONTH(NOW()) >= 2 AND MONTH(NOW()) <= 7 AND dh.oper_time >= CONCAT(YEAR(NOW()), '-02-01 00:00:00') AND dh.oper_time <= CONCAT(YEAR(NOW()), '-07-31 23:59:59')) OR (MONTH(NOW()) >= 8 AND dh.oper_time >= CONCAT(YEAR(NOW()), '-08-01 00:00:00') AND dh.oper_time <= CONCAT(YEAR(NOW()) + 1, '-01-31 23:59:59')) OR (MONTH(NOW()) = 1 AND dh.oper_time >= CONCAT(YEAR(NOW()) - 1, '-08-01 00:00:00') AND dh.oper_time <= CONCAT(YEAR(NOW()), '-01-31 23:59:59')) ) GROUP BY di.material_id, dh.tenant_id ) co ON m.id = co.material_id AND m.tenant_id = co.tenant_id LEFT JOIN ( -- 上期出库 SELECT di.material_id, dh.tenant_id, SUM(di.basic_number) as previous_out FROM jsh_depot_head dh INNER JOIN jsh_depot_item di ON dh.id = di.header_id WHERE dh.type = '出库' AND dh.status = '1' AND dh.delete_flag = '0' AND di.delete_flag = '0' AND ( -- 上期时间范围：根据当前月份判断 (MONTH(NOW()) >= 2 AND MONTH(NOW()) <= 7 AND dh.oper_time >= CONCAT(YEAR(NOW()) - 1, '-08-01 00:00:00') AND dh.oper_time <= CONCAT(YEAR(NOW()), '-01-31 23:59:59')) OR (MONTH(NOW()) >= 8 AND dh.oper_time >= CONCAT(YEAR(NOW()), '-02-01 00:00:00') AND dh.oper_time <= CONCAT(YEAR(NOW()), '-07-31 23:59:59')) OR (MONTH(NOW()) = 1 AND dh.oper_time >= CONCAT(YEAR(NOW()) - 1, '-02-01 00:00:00') AND dh.oper_time <= CONCAT(YEAR(NOW()) - 1, '-07-31 23:59:59')) ) GROUP BY di.material_id, dh.tenant_id ) po ON m.id = po.material_id AND m.tenant_id = po.tenant_id LEFT JOIN ( -- 本期入库 SELECT di.material_id, dh.tenant_id, SUM(di.basic_number) as current_in FROM jsh_depot_head dh INNER JOIN jsh_depot_item di ON dh.id = di.header_id WHERE dh.type = '入库' AND dh.status = '1' AND dh.delete_flag = '0' AND di.delete_flag = '0' AND ( -- 本期时间范围：根据当前月份动态判断 (MONTH(NOW()) >= 2 AND MONTH(NOW()) <= 7 AND dh.oper_time >= CONCAT(YEAR(NOW()), '-02-01 00:00:00') AND dh.oper_time <= CONCAT(YEAR(NOW()), '-07-31 23:59:59')) OR (MONTH(NOW()) >= 8 AND dh.oper_time >= CONCAT(YEAR(NOW()), '-08-01 00:00:00') AND dh.oper_time <= CONCAT(YEAR(NOW()) + 1, '-01-31 23:59:59')) OR (MONTH(NOW()) = 1 AND dh.oper_time >= CONCAT(YEAR(NOW()) - 1, '-08-01 00:00:00') AND dh.oper_time <= CONCAT(YEAR(NOW()), '-01-31 23:59:59')) ) GROUP BY di.material_id, dh.tenant_id ) ci ON m.id = ci.material_id AND m.tenant_id = ci.tenant_id LEFT JOIN ( -- 上期入库 SELECT di.material_id, dh.tenant_id, SUM(di.basic_number) as previous_in FROM jsh_depot_head dh INNER JOIN jsh_depot_item di ON dh.id = di.header_id WHERE dh.type = '入库' AND dh.status = '1' AND dh.delete_flag = '0' AND di.delete_flag = '0' AND ( -- 上期时间范围：根据当前月份判断 (MONTH(NOW()) >= 2 AND MONTH(NOW()) <= 7 AND dh.oper_time >= CONCAT(YEAR(NOW()) - 1, '-08-01 00:00:00') AND dh.oper_time <= CONCAT(YEAR(NOW()), '-01-31 23:59:59')) OR (MONTH(NOW()) >= 8 AND dh.oper_time >= CONCAT(YEAR(NOW()), '-02-01 00:00:00') AND dh.oper_time <= CONCAT(YEAR(NOW()), '-07-31 23:59:59')) OR (MONTH(NOW()) = 1 AND dh.oper_time >= CONCAT(YEAR(NOW()) - 1, '-02-01 00:00:00') AND dh.oper_time <= CONCAT(YEAR(NOW()) - 1, '-07-31 23:59:59')) ) GROUP BY di.material_id, dh.tenant_id ) pi ON m.id = pi.material_id AND m.tenant_id = pi.tenant_id WHERE m.delete_flag = '0'
AND m.id = #{materialId}
AND m.tenant_id = #{tenantId}
ON DUPLICATE KEY UPDATE bar_code = VALUES(bar_code), material_name = VALUES(material_name), material_model = VALUES(material_model), material_unit = VALUES(material_unit), current_period_stock = VALUES(current_period_stock), previous_period_stock = VALUES(previous_period_stock), current_period_out = VALUES(current_period_out), previous_period_out = VALUES(previous_period_out), current_period_in = VALUES(current_period_in), previous_period_in = VALUES(previous_period_in), last_calculation_time = CURRENT_TIMESTAMP

INSERT INTO jsh_daily_out_summary (
    material_id, bar_code, material_name, out_date, shop_name,
    total_out_quantity, depot_count, bill_count
)
VALUES (
    #{materialId},
    (SELECT me.bar_code FROM jsh_material_extend me WHERE me.material_id = #{materialId} AND me.default_flag = 1 LIMIT 1),
    (SELECT m.name FROM jsh_material m WHERE m.id = #{materialId} LIMIT 1),
    #{targetDate},
    #{shopName},
    (SELECT IFNULL(SUM(di.basic_number), 0) 
     FROM jsh_depot_item di 
     INNER JOIN jsh_depot_head dh ON dh.id = di.header_id 
     WHERE di.material_id = #{materialId} 
       AND DATE(dh.oper_time) = #{targetDate}
       AND dh.type = '出库' 
       AND dh.status = '1'
       AND IFNULL(di.delete_flag,'0') != '1'
       AND IFNULL(dh.delete_flag,'0') != '1'
       AND dh.shop_name = #{shopName}

           AND dh.tenant_id = #{tenantId}

    ),
    (SELECT COUNT(DISTINCT di.depot_id) 
     FROM jsh_depot_item di 
     INNER JOIN jsh_depot_head dh ON dh.id = di.header_id 
     WHERE di.material_id = #{materialId} 
       AND DATE(dh.oper_time) = #{targetDate}
       AND dh.type = '出库' 
       AND dh.status = '1'
       AND IFNULL(di.delete_flag,'0') != '1'
       AND IFNULL(dh.delete_flag,'0') != '1'
       AND dh.shop_name = #{shopName}

           AND dh.tenant_id = #{tenantId}

    ),
    (SELECT COUNT(DISTINCT dh.id) 
     FROM jsh_depot_item di 
     INNER JOIN jsh_depot_head dh ON dh.id = di.header_id 
     WHERE di.material_id = #{materialId} 
       AND DATE(dh.oper_time) = #{targetDate}
       AND dh.type = '出库' 
       AND dh.status = '1'
       AND IFNULL(di.delete_flag,'0') != '1'
       AND IFNULL(dh.delete_flag,'0') != '1'
       AND dh.shop_name = #{shopName}

           AND dh.tenant_id = #{tenantId}

     )
)
ON DUPLICATE KEY UPDATE
    total_out_quantity = VALUES(total_out_quantity),
    depot_count = VALUES(depot_count),
    bill_count = VALUES(bill_count),
    last_update_time = CURRENT_TIMESTAMP

-- 清空现有数据并重新初始化 DELETE FROM jsh_material_period_summary WHERE 1=1
AND tenant_id = #{tenantId} ;
DELETE FROM jsh_daily_out_summary WHERE 1=1
AND tenant_id = #{tenantId} ;
-- 插入基础的商品期间汇总数据 INSERT INTO jsh_material_period_summary ( material_id, bar_code, material_name, material_model, material_unit, current_period_stock, previous_period_stock, current_period_out, previous_period_out, current_period_in, previous_period_in ) SELECT m.id, (SELECT me.bar_code FROM jsh_material_extend me WHERE me.material_id = m.id AND me.default_flag = 1 LIMIT 1), m.name, m.model, m.unit, COALESCE((SELECT SUM(mcs.current_number) FROM jsh_material_current_stock mcs WHERE mcs.material_id = m.id AND mcs.delete_flag = '0'), 0), 0, COALESCE((SELECT SUM(di.basic_number) FROM jsh_depot_item di INNER JOIN jsh_depot_head dh ON dh.id = di.header_id WHERE di.material_id = m.id AND dh.type = '出库' AND dh.status = '1' AND di.delete_flag = '0' AND dh.delete_flag = '0'), 0), 0, COALESCE((SELECT SUM(di.basic_number) FROM jsh_depot_item di INNER JOIN jsh_depot_head dh ON dh.id = di.header_id WHERE di.material_id = m.id AND dh.type = '入库' AND dh.status = '1' AND di.delete_flag = '0' AND dh.delete_flag = '0'), 0), 0 FROM jsh_material m WHERE m.delete_flag = '0'
AND m.tenant_id = #{tenantId}
